 const deliveryTarget=e.target.closest('[data-delivery-field]');if(deliveryTarget){const f=deliveryTarget.dataset.deliveryField;$('#delivery-dialog').close();projectPhase=projectPhases.find(p=>p.fields.includes(f))?.id||'todo';pendingFocus='ensayo-'+f;if(current.page==='proyecto')render({keep:true});else location.hash='proyecto';return;}
 const anchor=e.target.closest('[data-class-anchor]');if(anchor){e.preventDefault();const target=document.getElementById(anchor.dataset.classAnchor);target?.scrollIntoView({block:'start',behavior:'instant'});if(target){target.tabIndex=-1;target.focus({preventScroll:true});}return;}
 const projectTarget=e.target.closest('[data-project-target]');if(projectTarget){projectPhase=projectTarget.dataset.projectTarget;if(current.page==='proyecto'){e.preventDefault();$('#project-stage').value=projectPhase;applyProjectPhase();main.querySelector('.essay-workshop:not([hidden]),.essay-closing:not([hidden])')?.scrollIntoView({block:'start',behavior:'instant'});return;}}
 if(e.target.closest('#course-index-toggle')){const open=document.body.dataset.courseIndex!=='open';document.body.dataset.courseIndex=open?'open':'closed';$('#course-index-toggle').setAttribute('aria-expanded',String(open));if(open)$('#sidebar a')?.focus();return;}
 if(e.target.closest('.skip')){e.preventDefault();(main.querySelector('h1')||main).focus();return;}
 if(e.target.closest('[data-owner-ok]'))unlockNotebook();
 const weekSummary=e.target.closest('.weekly-plan>details>summary');if(weekSummary)selectedWeek=Number(weekSummary.parentElement.id.slice(5));const classWeek=e.target.closest('[data-class-week]');if(classWeek){const week=Number(classWeek.dataset.classWeek),module=Math.ceil(week/4);presenter.show(module,state.routes[module]||'A','',week,classWeek.dataset.classDay||null);return;}
 const goto=e.target.closest('[data-goto-field]');if(goto?.closest('#delivery-dialog')&&$('#delivery-dialog').open)$('#delivery-dialog').close();if(goto){pendingFocus=goto.dataset.gotoField;if(goto.getAttribute('href')===location.hash){const target=document.getElementById(pendingFocus);if(target){for(let el=target.parentElement;el;el=el.parentElement)if(el.tagName==='DETAILS')el.open=true;target.focus();pendingFocus='';}}}
