$('#import-file').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>2000000)throw new Error('El archivo supera el tamaño máximo de 2 MB.');pendingImport=validateState(JSON.parse(await file.text()));const entries=Object.entries(pendingImport.notes).filter(([,n])=>Object.values(n).some(v=>v.trim()));$('#import-dialog').innerHTML=`<h2 id="import-title">Recuperar un cuaderno</h2><p>${count(entries.length,'sección con texto','secciones con texto')} · ${count(pendingImport.relations.length,'relación','relaciones')}${pendingImport.relationDraft?' · un borrador de relación pendiente':''}.</p><ul>${entries.map(([key])=>`<li>${keyNames[key]}</li>`).join('')}</ul><p>Importarlo reemplazará el cuaderno de este navegador. Descarga antes un respaldo si quieres conservarlo.</p><div class="export-actions">${button('export-json','Respaldar el cuaderno actual')}${button('cancel-import','Cancelar','button','autofocus')}${button('confirm-import','Reemplazar con este respaldo','button primary')}</div><p id="import-error" role="alert"></p>`;showDialog($('#import-dialog'));}catch(err){pendingImport=null;toast('No se importó el archivo. '+(err instanceof SyntaxError?'El contenido no es JSON válido.':err.message));}finally{e.target.value='';}});
