 if(action==='print-ficha'&&!locked){await session.idle();const key=e.target.closest('[data-action]').dataset.ficha,section=document.createElement('section');section.id='delivery-print';section.innerHTML=fichaHtml(state,key,fichaTitles[key],{includePreparation:!!$('#ficha-preparation')?.checked});document.body.append(section);document.body.dataset.print='delivery';window.print();return;}
