function activateDeskTab(tab){const parent=tab.closest('.essay-desk');parent.querySelectorAll('[role=tab]').forEach(el=>{const active=el===tab;el.setAttribute('aria-selected',String(active));el.tabIndex=active?0:-1;});parent.querySelectorAll('[role=tabpanel]').forEach(el=>el.hidden=el.id!=='desk-'+tab.dataset.deskTab);tab.focus({preventScroll:true});}
document.addEventListener('keydown',e=>{const tab=e.target.closest?.('[data-desk-tab]');if(!tab||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const tabs=[...tab.parentElement.querySelectorAll('[role=tab]')],i=tabs.indexOf(tab);activateDeskTab(tabs[e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length]);});
function showFichaDelivery(key){if(!fichaTitles[key])return;const checks=fichaChecklist(state,key),missing=checks.filter(c=>!c.ok),dest=workDestination(key,noteDestination(key));$('#delivery-dialog').innerHTML=`<div class="dialog-heading"><h2 id="delivery-title">Entregar · ${escape(fichaTitles[key])}</h2>${button('close-delivery','Cerrar','button','autofocus')}</div><p>La entrega breve incluye el argumento y los localizadores registrados. Integra en el argumento las referencias que aún falten. Puedes añadir la preparación como anexo y entregar el PDF por el canal que indique el docente.</p><section class="delivery-checklist" aria-labelledby="ficha-check-title"><h3 id="ficha-check-title">${missing.length?'Antes de entregar: '+count(missing.length,'aspecto pendiente','aspectos pendientes'):'Ficha lista para entregar'}</h3><ul>${checks.map(c=>`<li><strong>${c.ok?'Registrado':'Por revisar'}:</strong> ${c.ok?escape(c.label):`<a href="${dest.href}" class="text-link" data-goto-field="${key}-${c.field}">${escape(c.label)}</a>`}</li>`).join('')}</ul><p class="caption">Esta comprobación revisa presencia y extensión. Contrasta también la calidad del argumento con la rúbrica. Puedes guardar un borrador aunque queden pendientes.</p></section><fieldset class="delivery-choices"><legend>Contenido de esta entrega</legend><label><input type="checkbox" id="ficha-preparation" data-ficha-preparation="${key}" aria-describedby="ficha-preparation-help"> Adjuntar preparación y revisión</label><p id="ficha-preparation-help" class="caption">Añade como anexo la hipótesis, los pasajes y las revisiones que hayas registrado. Esta elección solo cambia el PDF; toda la preparación permanece en tu cuaderno y en el respaldo JSON.</p></fieldset><div class="export-actions">${button('print-ficha',missing.length?'Guardar PDF del borrador':'Imprimir / guardar como PDF','button primary',`data-ficha="${key}"`)}</div><h3>Vista previa</h3><div id="delivery-preview">${fichaHtml(state,key,fichaTitles[key])}</div>`;showDialog($('#delivery-dialog'));}
function showDelivery(){const choices=annexOptions(state),d=state.delivery,checks=deliveryChecklist(state),missing=checks.filter(c=>!c.ok);$('#delivery-dialog').innerHTML=`<div class="dialog-heading"><h2 id="delivery-title">Preparar mi entrega</h2>${button('close-delivery','Cerrar','button','autofocus')}</div><p>Ensayo, consigna y referencias forman el cuerpo. Selecciona los anexos pertinentes y revisa la vista previa.</p><section class="delivery-checklist" aria-labelledby="delivery-check-title"><h3 id="delivery-check-title">${missing.length?'Antes de entregar: '+count(missing.length,'aspecto pendiente','aspectos pendientes'):'Comprobación básica completada'}</h3><ul>${checks.map(c=>`<li><strong>${c.ok?'Registrado':'Por revisar'}:</strong> ${c.ok?escape(c.label):`<a href="#proyecto" class="text-link" data-delivery-field="${c.field}">${escape(c.label)}</a>`}</li>`).join('')}</ul><p class="caption">Esta comprobación revisa presencia y extensión. Contrasta también la calidad del argumento, las fuentes y la consigna con la rúbrica. Puedes guardar un borrador aunque queden pendientes.</p>${missing.length?button('review-delivery-field','Revisar el primer pendiente','text-button',`data-delivery-field="${missing[0].field}"`):''}</section><fieldset class="delivery-choices"><legend>Anexos que compartiré</legend>${choices.map(c=>`<label><input type="checkbox" data-annex="${escape(c.key)}" ${d.annexes.includes(c.key)?'checked':''}> ${escape(c.title)}</label>`).join('')||'<p>Todavía no hay actividades con texto para anexar.</p>'}<label><input type="checkbox" data-delivery-option="includeMap" ${d.includeMap?'checked':''}> Mapa y fuentes de las relaciones</label><label><input type="checkbox" data-delivery-option="includeAssessment" ${d.includeAssessment?'checked':''}> Autoevaluación con la rúbrica</label></fieldset><div class="export-actions">${button('print-delivery',missing.length?'Guardar PDF del borrador':'Imprimir / guardar como PDF','button primary')}${button('export-json','Guardar respaldo recuperable (.json)')}</div><p class="caption">En el diálogo de impresión elige «Guardar como PDF». Para continuar editando después, conserva también el JSON.</p><div id="delivery-preview" aria-label="Vista previa de la entrega">${deliveryHtml(state)}</div>`;showDialog($('#delivery-dialog'));}
document.addEventListener('change',e=>{if(locked)return;const ficha=e.target.dataset.fichaPreparation;if(ficha&&fichaTitles[ficha]){$('#delivery-preview').innerHTML=fichaHtml(state,ficha,fichaTitles[ficha],{includePreparation:e.target.checked});return;}const annex=e.target.dataset.annex,option=e.target.dataset.deliveryOption;if(annex){state.delivery.annexes=state.delivery.annexes.filter(k=>k!==annex);if(e.target.checked)state.delivery.annexes.push(annex);}else if(['includeMap','includeAssessment'].includes(option))state.delivery[option]=e.target.checked;else return;save();$('#delivery-preview').innerHTML=deliveryHtml(state);});
